films.V135GrandmaEvHook:
// V135GrandmaEvHook: the struck word. Frame 0 already reads the claim (Mtavruli, big, ink on paper) over the 1899 plate
// of the record car, shown whole; on frame 2 a red ink strike runs through it, on the year's chunk the stamp rolls back
// from today's year to 1899, and on the "me" line an ink circle lands round the car on the plate.
import React from 'react';
import {Img, staticFile, useCurrentFrame} from 'remotion';
import {cueFrame, Haptic} from '../common';
import {C} from '../../tokens';
import {spr} from '../../lib/anim';
import {TXT} from '../../lib/layer';
import type {SceneCtx} from '../../types';
import {Card, drift, FitText, RollDigits, S} from '../kit/p2';
import {Ink} from '../kit/ink';

type P = {
  claim?: string; // the struck word, readable at frame 0
  src?: string; // the plate (public/photos)
  year?: string; // the stamp the rewind lands on
  from?: string; // where the rewind starts
  yearAt?: number | string; // the chunk the year rolls on
  ringAt?: number | string; // the chunk the ring lands on
  ring?: {x: number; y: number; w: number; h: number}; // the car on the plate (plate fractions)
};

// the plate: 1600 x 1167, shown whole
const PW = 800;
const PH = Math.round((PW * 1167) / 1600);
const PX = 540 - PW / 2;
const PY = 1360 - PH;

export const V135GrandmaEvHook: React.FC<{p: P; ctx: SceneCtx}> = ({p, ctx}) => {
  const frame = useCurrentFrame();
  const yearAt = Math.max(8, cueFrame(ctx, p.yearAt ?? 1));
  const ringAt = Math.max(16, cueFrame(ctx, p.ringAt ?? '0.9s'));
  const r = p.ring ?? {x: 0.18, y: 0.3, w: 0.66, h: 0.5};
  const stamp = spr(frame, yearAt, 'punch');
  const claimY = S.top;
  const yearY = claimY + 250;
  return (
    <div style={{position: 'absolute', inset: 0, backgroundColor: C.bg}}>
      <div style={{position: 'absolute', inset: 0, ...drift(frame, ctx.dur, {x: 540, y: 900})}}>
        <Card x={PX} y={PY} w={PW} h={PH} r={18}>
          <Img src={staticFile('photos/story-ev-is-old-2.jpg')} style={{position: 'absolute', left: 0, top: 0, width: PW, height: PH, objectFit: 'contain', filter: 'grayscale(1) contrast(1.1)'}} />
        </Card>
        <FitText text={p.claim ?? ''} x={540} y={claimY} w={S.right - S.left} size={210} min={120} maxLines={1} weight={700} align="center" anim="none" />
        {p.year ? (
          <div className={TXT} style={{position: 'absolute', left: 0, width: 1080, top: yearY, textAlign: 'center', opacity: frame < yearAt ? 0 : Math.min(1, stamp * 1.4), transform: `scale(${(1.2 - 0.2 * Math.min(1, stamp)).toFixed(4)})`}}>
            <RollDigits text={p.year} from={p.from} at={yearAt} size={170} dur={22} />
          </div>
        ) : null}
      </div>
      <Ink
        end={ctx.dur}
        marks={[
          {kind: 'strike', box: {x: 250, y: claimY + 40, w: 580, h: 130}, at: 2},
          {kind: 'circle', box: {x: PX + r.x * PW, y: PY + r.y * PH, w: r.w * PW, h: r.h * PH}, at: ringAt},
        ]}
      />
      <Haptic kind="rigid" at={yearAt + 2} volume={0.3} />
    </div>
  );
};

films.V135GrandmaEv:
// V135GrandmaEv: the record run, read off the car itself. The real La Jamais Contente sits whole on the paper as a plate;
// under it the speed counts up through real values, a scale fills in the data accent, and when it passes the inked 100
// line the line is struck and the last digits land with a ring round the figure.
import React from 'react';
import {Img, staticFile, useCurrentFrame} from 'remotion';
import {cueFrame, Haptic, Land, lead, Sfx} from '../common';
import {C} from '../../tokens';
import {ease, prog, spr} from '../../lib/anim';
import {OBJ, TXT} from '../../lib/layer';
import type {SceneCtx} from '../../types';
import {Card, drift, FitText, Quiet, RollDigits, S, tone} from '../kit/p2';
import {Ink} from '../kit/ink';

type P = {
  shot?: 'record' | 'twist';
  word?: string; // the twist's one word
  src?: string; // the car (public/photos)
  source?: string; // the photo's credit line, shown under it
  value?: string; // the whole part of the speed
  rest?: string; // its decimals, landing on the hit
  unit?: string;
  line?: number; // the inked line the speed passes
  max?: number; // the scale's end
  hitAt?: number | string;
};

// the plate: 1600 x 1200, shown whole
const PW = 640;
const PH = 480;
const PX = 540 - PW / 2;
const PY = S.top + 10;
const BAR_Y = 1300;
const BAR_X = S.left;
const BAR_W = S.right - S.left;

/** THE TWIST: Porsche's car whole on the paper, an ink arrow at it while the line sets up, then the one word slams in under
 *  it on the twist's chunk (the camera kicks, the hold rides on it). */
const TW = 820;
const TH = Math.round((TW * 1067) / 1600);
const TX = 540 - TW / 2;
const TY = S.top + 20;
const TwistShot: React.FC<{p: P; ctx: SceneCtx}> = ({p, ctx}) => {
  const frame = useCurrentFrame();
  const base = lead(ctx);
  const hit = Math.max(base + 20, cueFrame(ctx, p.hitAt ?? 1));
  return (
    <div style={{position: 'absolute', inset: 0, backgroundColor: C.bg}}>
      <div style={{position: 'absolute', inset: 0, ...drift(frame, ctx.dur, {x: 540, y: 800})}}>
        <Card x={TX} y={TY} w={TW} h={TH} r={18}>
          <Img src={staticFile('photos/story-ev-is-old-5.jpg')} style={{position: 'absolute', left: 0, top: 0, width: TW, height: TH, objectFit: 'cover', filter: 'grayscale(1) contrast(1.08)'}} />
        </Card>
        {p.source ? <Quiet text={p.source} x={540} y={TY + TH + 8} w={TW} align="center" latin /> : null}
        <FitText text={p.word ?? ''} x={540} y={TY + TH + 90} w={S.right - S.left} size={200} min={110} maxLines={1} weight={700} align="center" at={hit} anim="slam" />
      </div>
      <Ink end={ctx.dur} marks={[{kind: 'arrow', box: {x: TX + TW * 0.55, y: TY + TH * 0.2, w: TW * 0.3, h: TH * 0.35}, at: base + 6}]} />
      <Sfx name="asmr-whoomp" at={hit} volume={0.4} />
      <Land at={hit} />
      <Haptic kind="rigid" at={hit + 2} volume={0.3} />
    </div>
  );
};

export const V135GrandmaEv: React.FC<{p: P; ctx: SceneCtx}> = ({p, ctx}) => (p.shot === 'twist' ? <TwistShot p={p} ctx={ctx} /> : <Record p={p} ctx={ctx} />);

/** THE RECORD (the signature shot). */
const Record: React.FC<{p: P; ctx: SceneCtx}> = ({p, ctx}) => {
  const frame = useCurrentFrame();
  const base = lead(ctx);
  const value = Number(p.value ?? '105');
  const line = p.line ?? 100;
  const max = p.max ?? 120;
  const hit = Math.max(base + 30, cueFrame(ctx, p.hitAt ?? 1));
  const runAt = base + 4;
  const run = Math.max(16, hit - runAt);
  const u = ease.data(prog(frame, runAt, run));
  const lineX = BAR_X + (BAR_W * line) / max;
  const fillW = (BAR_W * value * u) / max;
  const land = spr(frame, hit, 'punch');
  const digitsY = PY + PH + 56;
  return (
    <div style={{position: 'absolute', inset: 0, backgroundColor: C.bg}}>
      <div style={{position: 'absolute', inset: 0, ...drift(frame, ctx.dur, {x: 540, y: 1000})}}>
        <Card x={PX} y={PY} w={PW} h={PH} r={18}>
          <Img src={staticFile('photos/story-ev-is-old-3.jpg')} style={{position: 'absolute', left: 0, top: 0, width: PW, height: PH, objectFit: 'cover', filter: 'grayscale(1) contrast(1.08)'}} />
        </Card>
        {p.source ? <Quiet text={p.source} x={540} y={PY + PH + 8} w={820} align="center" latin /> : null}
        <div className={TXT} style={{position: 'absolute', left: S.left, top: digitsY, display: 'flex', alignItems: 'baseline', gap: 10}}>
          <RollDigits text={String(value)} at={runAt} dur={run} size={196} />
          <span style={{fontFamily: 'inherit', fontWeight: 700, fontSize: 128, color: tone('ink'), opacity: frame < hit ? 0 : Math.min(1, land * 1.4), transform: `translateY(${((1 - Math.min(1, land)) * -30).toFixed(2)}px)`, display: 'inline-block'}}>{p.rest ?? ''}</span>
        </div>
        <FitText text={p.unit ?? ''} x={S.left} y={BAR_Y - 74} w={320} size={52} min={40} maxLines={1} weight={600} align="left" t="quiet" at={runAt + 6} latin />
        <div className={OBJ} style={{position: 'absolute', left: BAR_X, top: BAR_Y, width: BAR_W, height: 26, borderRadius: 13, backgroundColor: C.rule}}>
          <div style={{position: 'absolute', left: 0, top: 0, height: 26, width: fillW, borderRadius: 13, backgroundColor: tone('accent')}} />
        </div>
        <div style={{position: 'absolute', left: lineX - 4, top: BAR_Y - 14, width: 8, height: 54, borderRadius: 4, backgroundColor: C.ink}} />
        <FitText text={String(line)} x={lineX - 150} y={BAR_Y - 84} w={300} size={52} min={40} maxLines={1} weight={700} align="center" at={base} latin />
      </div>
      <Ink sound={false} end={ctx.dur} marks={[{kind: 'circle', box: {x: S.left - 20, y: digitsY + 6, w: 640, h: 210}, at: hit + 4}]} />
      <Sfx name="asmr-count-roll" at={runAt} volume={0.3} />
      <Land at={hit} />
      <Haptic kind="rigid" at={hit + 2} volume={0.3} />
    </div>
  );
};
